/**
 * Runtime asset manifest (generated by tools/art/extract.py from Codex sources)
 * and small procedural effect textures drawn by code.
 */
import manifestJson from '../data/assetManifest.json';
import type { CharacterId, TreasureId } from '../domain/types';
import { FRIEND_SIZE, type CellCut, type FriendFrame } from '../platform/layout';
import type { RigAsset } from './rigData';

export type Reaction = 'idle' | 'drawing' | 'encouragement' | 'celebration' | 'talk';
/** Corner-tier atlas groups (loaded and released independently) and the stage tier. */
export type AtlasGroup = 'idle' | 'wave' | 'more' | 'stage';

export interface CharacterAsset {
  /** Multiatlas JSON per group (tools/art/v3.py). */
  atlases: Record<AtlasGroup, string>;
  decodedBytes: Record<AtlasGroup, number>;
  bytes: number;
  /** Corner-tier frame (untrimmed canvas) size. */
  frameWidth: number;
  frameHeight: number;
  /** Stage tier (quest intro pose) frame size. */
  stage: { frameWidth: number; frameHeight: number };
  pivot: { x: number; y: number };
  /** Fraction of the frame height at the bottom (the waist cut) that fades out. */
  cutFade: number;
  /** Painted area of idle-00 as fractions of the frame. */
  content: { x: number; y: number; w: number; h: number };
  /** Union of the painted areas of every frame but the celebration. */
  contentActive: { x: number; y: number; w: number; h: number };
  sequences: Record<Reaction, string[]>;
  /** Key poses available in the stage tier. */
  stageSequences: Record<'idle' | 'encouragement', string[]>;
}

export interface ItemAsset {
  image: string;
  width: number;
  height: number;
}

export interface AtlasAsset {
  atlas: string;
  bytes: number;
  decodedBytes: number;
}

/** One painted layer of a leaf curtain: where it sits on the shared canvas (canvas px). */
export interface EntryLayer {
  name: string;
  image: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

/**
 * The entry's layered leaf curtains (tools/art/entry.py, art/CLAUDE_HANDOFF_ENTRY.md):
 * back, mid, front-top, front-bottom per side on one canvas, the glowing
 * clearing behind them, and six single leaves for the start-button burst.
 */
export interface EntryAssets {
  canvas: [number, number];
  /** Canvas px that must stay beyond the screen's outer, top and bottom edges. */
  overscan: number;
  left: EntryLayer[];
  right: EntryLayer[];
  backing: ItemAsset;
  leaves: ItemAsset[];
}

export interface IntroAssets {
  lightShafts: ItemAsset;
  /** `cut`: the cell's straight left and bottom edges and their fade (tools/art/v3.py). */
  gigantoPeek: AtlasAsset & { frames: string[]; frameSize: number; cut?: CellCut };
  popups: AtlasAsset & { cellSize: number };
  dust: AtlasAsset & { frames: string[] };
  sprout: { stages: string[]; width: number; height: number; soil: { x: number; y: number } };
  titleSign: ItemAsset & { loops: Array<{ x: number; y: number }>; plank: { top: number; bottom: number } };
  vine: ItemAsset & { bottomX: number };
}

interface Manifest {
  characters: Record<CharacterId, CharacterAsset>;
  /** Treasures with art; new ones join when Codex delivers them (treasureHasArt). */
  treasures: Partial<Record<TreasureId, ItemAsset>>;
  foliage: Record<string, ItemAsset>;
  ui: Record<string, ItemAsset>;
  backgrounds: Record<'jungle' | 'collection' | 'ground', ItemAsset>;
  intro: IntroAssets;
  entry: EntryAssets;
  /** Painted parts of the treasures and the butterfly, one atlas (tools/art/rigs.py). */
  rigs?: { atlas?: string; decodedBytes?: number; assets?: Record<string, RigAsset> };
  /** The chest on the collection button: closed layers, open pose, lid hinge (fractions). */
  chest?: { base?: string; lid?: string; open?: string; width?: number; height?: number; lidPivot?: [number, number] };
}

export const ASSETS = manifestJson as unknown as Manifest;

/** A treasure's or the butterfly's rig, when its painted parts exist. */
export function rigFor(id: string): RigAsset | null {
  return (ASSETS.rigs?.atlas && ASSETS.rigs.assets?.[id]) || null;
}

/** Size and painted area of a friend's frame, for layout. */
export function friendFrame(id: CharacterId): FriendFrame {
  const c = ASSETS.characters[id];
  return {
    aspect: c.frameWidth / c.frameHeight,
    size: FRIEND_SIZE[id] ?? 1,
    content: c.contentActive,
    ...(id === 'giganto' ? { flushLeft: true, bleed: 0.12 } : {}),
  };
}

/**
 * How far below the screen edge a friend's base rests (px), for a frame shown
 * `displayHeight` px tall: the faded band of the waist cut plus a little more,
 * so at rest the bust ends cleanly at the screen edge.
 */
export function baseHidden(id: CharacterId, displayHeight: number): number {
  return Math.ceil(displayHeight * (ASSETS.characters[id].cutFade ?? 0)) + 2;
}

/**
 * Which way each friend's painted body and face point (checked on the V3
 * frames, 14 Oct 2026). On a maze the friend stands at the lower left
 * (FRIEND_CORNER), so nobody may face left, away from the board; a friend
 * drawn facing left would need mirroring there (tests/domain/layout.test.ts).
 */
export const FACING: Record<CharacterId, 'left' | 'right' | 'front'> = {
  giganto: 'right',
  mazu: 'right',
  bill: 'right',
  rocky: 'front',
  tiny: 'front',
};

/** Welcome cast height relative to the base: Giganto a bit taller than the friends. */
export const CAST_SCALE: Record<CharacterId, number> = { giganto: 1.08, bill: 0.88, tiny: 0.88, mazu: 0.88, rocky: 0.88 };

/** Resolve a manifest path against the deployed base URL. */
export function assetUrl(path: string): string {
  return `${import.meta.env.BASE_URL}${path}`;
}

function canvas(w: number, h: number): [HTMLCanvasElement, CanvasRenderingContext2D] {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  if (!g) throw new Error('2D canvas unavailable');
  return [c, g];
}

/** Soft round glow, white (tint at runtime). */
export function sparkTexture(): HTMLCanvasElement {
  const [c, g] = canvas(64, 64);
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.35, 'rgba(255,255,255,0.55)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 64, 64);
  return c;
}

/** A small three-toed paw print (pointing up), drawn with the board's footprint shape. */
export function pawTexture(draw: (g: CanvasRenderingContext2D, x: number, y: number, size: number, angle: number) => void): HTMLCanvasElement {
  const [c, g] = canvas(64, 64);
  g.fillStyle = 'rgba(120, 76, 32, 0.62)';
  draw(g, 32, 34, 52, -Math.PI / 2);
  return c;
}

/** A soft grain of sand (tinted at runtime) for the puffs under the drawing tip. */
export function grainTexture(): HTMLCanvasElement {
  const [c, g] = canvas(16, 16);
  const grad = g.createRadialGradient(8, 8, 0, 8, 8, 8);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.6, 'rgba(255,255,255,0.7)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 16, 16);
  return c;
}

/** Four-point glint star. */
export function starTexture(): HTMLCanvasElement {
  const [c, g] = canvas(64, 64);
  g.translate(32, 32);
  const grad = g.createRadialGradient(0, 0, 0, 0, 0, 30);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(1, 'rgba(255,250,220,0)');
  g.fillStyle = grad;
  g.beginPath();
  for (let i = 0; i < 8; i++) {
    const r = i % 2 === 0 ? 30 : 5;
    const a = (i / 8) * Math.PI * 2 - Math.PI / 2;
    g.lineTo(Math.cos(a) * r, Math.sin(a) * r);
  }
  g.closePath();
  g.fill();
  return c;
}

/** Friendly pointing hand for the first-puzzle demonstration. */
export function handTexture(): HTMLCanvasElement {
  const [c, g] = canvas(96, 120);
  g.lineJoin = 'round';
  g.lineCap = 'round';
  const skin = '#ffe2c2';
  const line = '#8a5a2b';
  g.lineWidth = 4;
  g.strokeStyle = line;
  g.fillStyle = skin;
  // Index finger (pointing up; fingertip is the hotspot at top).
  g.beginPath();
  g.moveTo(34, 60);
  g.lineTo(34, 14);
  g.arc(44, 14, 10, Math.PI, 0);
  g.lineTo(54, 60);
  g.closePath();
  g.fill();
  g.stroke();
  // Fist.
  g.beginPath();
  g.moveTo(24, 58);
  g.quadraticCurveTo(22, 108, 52, 112);
  g.quadraticCurveTo(84, 110, 82, 70);
  g.quadraticCurveTo(80, 52, 66, 54);
  g.quadraticCurveTo(54, 50, 34, 54);
  g.quadraticCurveTo(24, 54, 24, 58);
  g.closePath();
  g.fill();
  g.stroke();
  g.beginPath();
  g.moveTo(54, 66);
  g.quadraticCurveTo(66, 64, 80, 70);
  g.moveTo(52, 80);
  g.quadraticCurveTo(66, 78, 80, 84);
  g.stroke();
  return c;
}

/** Soft ring used for the entrance invitation. */
export function ringTexture(): HTMLCanvasElement {
  const [c, g] = canvas(128, 128);
  g.strokeStyle = 'rgba(255,255,255,0.95)';
  g.lineWidth = 7;
  g.shadowColor = 'rgba(255,255,255,0.9)';
  g.shadowBlur = 10;
  g.beginPath();
  g.arc(64, 64, 50, 0, Math.PI * 2);
  g.stroke();
  return c;
}
